import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, fn, userEvent, within } from 'storybook/test';
import { MemoryRouter } from 'react-router-dom';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { ZimmLink } from '.';

const meta: Meta<typeof ZimmLink> = {
  title: 'Elements/ZimmLink',
  component: ZimmLink,
  argTypes: {
    size: { control: 'radio', options: ['large', 'small'] },
    label: { control: 'text' },
  },
  // ZimmLink calls useSafeHref() unconditionally (regional link prefixing) — same provider shape
  // drawer-menu/index.stories.tsx uses for the useMultiSite() this hook wraps. Identity buildUrl
  // here since none of the stories below assert on prefixing; see the dedicated RegionalHref
  // story for that.
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider
          site={{ id: 'ZimmermannAU', alias: 'au' }}
          locale={{ id: 'en-AU', alias: 'en-AU' }}
          buildUrl={(path: string) => path}
        >
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmLink>;

export const Default: Story = {
  args: { label: 'Shop now', size: 'large', href: '#' },
};

export const Small: Story = {
  args: { label: 'Find your size', size: 'small', href: '#' },
};

export const ButtonLarge: Story = {
  name: 'Button — Large',
  args: { label: 'Shop now', size: 'large', onClick: fn() },
};

export const ButtonSmall: Story = {
  name: 'Button — Small',
  args: { label: 'Find your size', size: 'small', onClick: fn() },
};

export const ClickInteraction: Story = {
  name: 'Click Interaction',
  args: { label: 'Find your size', size: 'small', onClick: fn() },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const link = canvas.getByRole('button', { name: /find your size/i });
    await userEvent.click(link);
    await expect(args.onClick).toHaveBeenCalledOnce();
  },
};

export const RegionalHref: Story = {
  name: 'Regional Href — carries the current site/locale prefix',
  args: { label: 'New Arrivals', href: '/new-arrivals' },
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider
          site={{ id: 'ZimmermannUK', alias: 'uk' }}
          locale={{ id: 'en-GB', alias: 'en-GB' }}
          buildUrl={(path: string) => `/uk${path}`}
        >
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    // Regression coverage for the regional-link bug: an internal href must be run through
    // useSafeHref() so the rendered anchor carries the current site's URL prefix.
    await expect(canvas.getByRole('link', { name: 'New Arrivals' })).toHaveAttribute('href', '/uk/new-arrivals');
  },
};

