import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { expect, userEvent, within } from 'storybook/test';
import { MemoryRouter } from 'react-router-dom';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { ZimmCartItemActions } from '.';
import type { WishlistMoveResult } from '.';

const meta: Meta<typeof ZimmCartItemActions> = {
  title: 'Commerce/ZimmCartItemActions',
  component: ZimmCartItemActions,
  parameters: { layout: 'padded' },
  // ZimmCartItemActions renders ZimmLink, which calls useSafeHref() unconditionally (regional
  // link prefixing) — same provider shape zimmLink/index.stories.tsx uses for the useMultiSite()
  // this hook wraps. Identity buildUrl here since no story below asserts on prefixing.
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider
          site={{ id: 'ZimmermannAU', alias: 'au' }}
          locale={{ id: 'en-AU', alias: 'en-AU' }}
          buildUrl={(path: string) => path}
        >
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};
